package avscenario

import (
	"path/filepath"
	"testing"

	"github.com/audspect/bas/internal/scenario"
)

// TestShippedAVNGAVScenario_LoadsThroughRealEngine_ConsoleDispatchable is
// the proof that av-ngav-assessment.yaml (generated by
// scripts/av-scenario-builder from this package's own
// AudspectAVAssessmentScenario) is not just a validated in-memory Go
// value, but a real, signed, shipped scenario file the production
// engine -- using the real compiled-in signature verifier, the exact
// path a console user's scenario picker goes through -- accepts and
// loads as "builtin". Before this test (and the file it loads), no
// scenario existed anywhere under scenarios/ that exercised any
// internal/avcatalog vector; a console user had no way to run one.
func TestShippedAVNGAVScenario_LoadsThroughRealEngine_ConsoleDispatchable(t *testing.T) {
	dir, err := filepath.Abs(filepath.Join("..", "..", "..", "scenarios"))
	if err != nil {
		t.Fatal(err)
	}
	e := scenario.NewEngine(dir) // default verifier == integrity.CompiledVerifier{}, same as production
	if err := e.Load(); err != nil {
		t.Fatalf("engine load: %v", err)
	}

	loaded := e.List()
	var found *scenario.Scenario
	for _, s := range loaded {
		if s.ID == "av-ngav-assessment" {
			found = s
			break
		}
	}
	if found == nil {
		t.Fatal("av-ngav-assessment was not loaded by the real engine -- either missing, unsigned, or it failed signature verification")
	}
	if found.Source != "builtin" {
		t.Errorf("Source = %q, want builtin", found.Source)
	}
	if len(found.Steps) == 0 {
		t.Error("expected at least one step")
	}

	want, err := AudspectAVAssessmentScenario()
	if err != nil {
		t.Fatalf("AudspectAVAssessmentScenario: %v", err)
	}
	if len(found.Steps) != len(want.Steps) {
		t.Errorf("loaded scenario has %d steps, want %d (the shipped YAML is stale relative to the current catalog -- re-run scripts/av-scenario-builder and re-sign)", len(found.Steps), len(want.Steps))
	}
}
